const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:50000' },
      { kind: 'text', payload: '图上距离 4 厘米' },
      { kind: 'text', payload: '实际距离 200000 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.round(W * 0.18);
    var x1 = Math.round(W * 0.82);
    var y = Math.round(H * 0.60);
    var mid = Math.round((x0 + x1) / 2);
    var t = 26;
    var paths = [
      { id: 'seg', commands: [['M', x0, y], ['L', x1, y]] },
      { id: 'tickL', commands: [['M', x0, y - t], ['L', x0, y + t]] },
      { id: 'tickR', commands: [['M', x1, y - t], ['L', x1, y + t]] },
      { id: 'tickM', commands: [['M', mid, y - 14], ['L', mid, y + 14]] }
    ];
    return {
      schemaVersion: 1,
      sceneId: 'scale-bar-4cm',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: [
        { type: 'path', pathId: 'seg', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 'tickL', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 'tickR', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
        { type: 'path', pathId: 'tickM', fill: '#8a97a8', stroke: { width: 2, cap: 'round' } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0, y: Math.round(H * 0.16) }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: mid, y: y - 30 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: mid, y: y + 34 }, hAlign: 'center', vAlign: 'top', color: '#26354a' }
      ] }
    };
  }
};
